const cfg = $input.first()?.json || {};
if (!cfg.apiKey) throw new Error('Config missing apiKey');

const apiBaseUrl = String(cfg.apiBaseUrl || 'https://services.leadconnectorhq.com').replace(/\/$/, '');
const apiKey = String(cfg.apiKey || '').trim();
const locationId = String(cfg.locationId || '').trim();
const sourceSystem = String(cfg.sourceSystem || 'ghl_social');

const headers = {
  Authorization: 'Bearer ' + apiKey,
  Version: '2021-04-15',
  'Content-Type': 'application/json',
  Accept: 'application/json',
};

const batchId = 'lt-social-' + new Date().toISOString().replace(/[:.]/g, '-');
const now = new Date().toISOString();

// Fetch posts via POST /social-media-posting/{locationId}/posts/list
let response;
try {
  response = await this.helpers.httpRequest({
    method: 'POST',
    url: apiBaseUrl + '/social-media-posting/' + encodeURIComponent(locationId) + '/posts/list',
    headers,
    body: {},
    json: true,
    timeout: 60000,
  });
} catch (error) {
  const body = error?.response?.body || error?.message || error;
  return [{ json: { ok: false, error: 'GHL social posts failed', detail: String(body).substring(0, 300), batchId } }];
}

const posts = Array.isArray(response?.results?.posts) ? response.results.posts : [];

if (posts.length === 0) {
  return [{ json: { ok: true, skipped: true, reason: 'no_posts', batchId } }];
}

return posts.map(function(p) {
  return {
    json: {
      post_id: p._id || p.id || '',
      account_id: p.accountId || '',
      platform: p.platform || 'unknown',
      type: p.type || 'post',
      status: p.status || 'draft',
      summary: p.summary || '',
      error_message: p.error || '',
      published_at: p.publishedAt || null,
      scheduled_at: p.scheduleDate || null,
      created_at: p.createdAt || null,
      updated_at: p.updatedAt || null,
      insights: p.insights || {},
      payload_json: p,
      batch_id: batchId,
      loaded_at: now
    }
  };
});

